    {
        return $this->hasMany(Break::class);
    }

    public function appointments()
    {
        return $this->hasMany(Appointment::class);
    }

    public function getAvailableSlots(Carbon $date)
    {
        // Get the service schedule for the given day
        $schedule = $this->availability()->where('day_of_week', $date->format('l'))->first();

        if (!$schedule) {
            return [];
        }

        // Initialize available slots
        $availableSlots = [];
        $startTime = Carbon::createFromTime($schedule->start_time->hour, $schedule->start_time->minute, 0, $date->toDateString());
        $endTime = Carbon::createFromTime($schedule->end_time->hour, $schedule->end_time->minute, 0, $date->toDateString());

        // Generate initial slots
        while ($startTime->lt($endTime)) {
            $slotEndTime = $startTime->copy()->addMinutes($this->duration_minutes);
            if ($slotEndTime->lte($endTime)) {
                $availableSlots[] = [
                    'start_time' => $startTime->copy(),
                    'end_time' => $slotEndTime->copy()
                ];
            }
            $startTime->addMinutes($this->duration_minutes + $this->break_minutes);
        }

        // Exclude break times
        $breaks = $this->breaks()->whereDate('date', $date->toDateString())->get();
        foreach ($breaks as $break) {
            $breakStartTime = Carbon::createFromTime($break->start_time->hour, $break->start_time->minute, 0, $date->toDateString());
            $breakEndTime = Carbon::createFromTime($break->end_time->hour, $break->end_time->minute, 0, $date->toDateString());
            $availableSlots = array_filter($availableSlots, function ($slot) use ($breakStartTime, $breakEndTime) {
                return !($slot['start_time']->lt($breakEndTime) && $slot['end_time']->gt($breakStartTime));
            });
        }

        // Exclude existing bookings
        $bookings = $this->appointments()->whereDate('start_time', $date->toDateString())->get();
        foreach ($bookings as $booking) {
            $bookingStartTime = $booking->start_time;
            $bookingEndTime = $booking->end_time;
            $availableSlots = array_filter($availableSlots, function ($slot) use ($bookingStartTime, $bookingEndTime) {
                return !($slot['start_time']->lt($bookingEndTime) && $slot['end_time']->gt($bookingStartTime));
            });
        }

        return $availableSlots;
    }
}
