import 'dart:typed_data';
import 'dart:io';
import 'package:image/image.dart' as img;

Future<List<Uint8List>> sliceImageIntoFour(String imagePath) async {
  try {
    // Read the image file from the specified path
    final File imageFile = File(imagePath);
    if (!imageFile.existsSync()) {
      throw FileSystemException('File not found at path: $imagePath');
    }

    // Read the image file as bytes
    final Uint8List imageData = await imageFile.readAsBytes();

    // Decode the image data
    final img.Image? image = img.decodeImage(imageData);
    if (image == null) {
      throw Exception('Unsupported image format or invalid image data.');
    }

    // Get the dimensions of the image
    final int width = image.width;
    final int height = image.height;

    // Calculate the center point
    final int centerX = width ~/ 2;
    final int centerY = height ~/ 2;

    // Explicitly divide the image into four equal parts from the center
    final List<Uint8List> slicedImagesBytes = [
      imageData.sublist(0, centerX * centerY * 4), // Top-left
      imageData.sublist(centerX * centerY * 4, (centerX * height + width * centerY) * 2), // Top-right
      imageData.sublist((centerX * height + width * centerY) * 2, (width * height) * 3 ~/ 4), // Bottom-left
      imageData.sublist((width * height) * 3 ~/ 4, imageData.length), // Bottom-right
    ];

    return slicedImagesBytes;
  } catch (e) {
    throw Exception('Error processing image: $e');
  }
}

// Example usage:
