function source_panel_method()
    % Read panel points from a text file
    filename = 'panel_points.txt';

    % Check if the file exists
    if ~exist(filename, 'file')
        error('File not found: %s', filename);
    end

    try
        panel_points = read_panel_points(filename);
    catch ME
        error('Error reading panel points: %s', ME.message);
    end

    % Ask user for flow conditions
    try
        V_inf = input('Enter the free stream velocity: ');
        if ~isnumeric(V_inf) || isnan(V_inf) || isinf(V_inf) || V_inf <= 0
            error('Invalid free stream velocity. Please enter a positive numeric value.');
        end
    catch ME
        error('Invalid input for free stream velocity: %s', ME.message);
    end

    try
        alpha_deg = input('Enter the angle of attack (in degrees): ');
        if ~isnumeric(alpha_deg) || isnan(alpha_deg) || isinf(alpha_deg)
            error('Invalid angle of attack. Please enter a numeric value.');
        end
        alpha = deg2rad(alpha_deg);
    catch ME
        error('Invalid input for angle of attack: %s', ME.message);
    end

    % Define the range of panel numbers to test
    panel_numbers = [10, 20, 40, 80];

    % Experimental or analytical results for comparison
    try
        Cp_exp = [0.5, 0.3, 0.1, -0.1, -0.3, -0.5]; % Example data
        Cl_exp = 0.8; % Example data

        if ~isnumeric(Cp_exp) || any(isnan(Cp_exp)) || any(isinf(Cp_exp))
            error('Invalid experimental pressure coefficients. Please provide a numeric array.');
        end

        if ~isnumeric(Cl_exp) || isnan(Cl_exp) || isinf(Cl_exp)
            error('Invalid experimental lift coefficient. Please provide a numeric value.');
        end
    catch ME
        error('Error in experimental data: %s', ME.message);
    end

    % Initialize arrays to store results
    Cl_results = zeros(length(panel_numbers), 1);
    Cp_errors = cell(length(panel_numbers), 1);

    for k = 1:length(panel_numbers)
        n_panels = panel_numbers(k);

        % Distribute panel points
        try
            distributed_points = distribute_panels(panel_points, n_panels);
        catch ME
            error('Error distributing panels: %s', ME.message);
        end

        % Initialize variables
        A = zeros(n_panels, n_panels);
        b = -V_inf * cos(alpha) * ones(n_panels, 1);

        % Compute influence coefficients
        try
            for i = 1:n_panels
                for j = 1:n_panels
                    if i ~= j
                        A(i, j) = compute_influence_coefficient(distributed_points(i, :), distributed_points(j, :));
                    else
                        A(i, j) = 0.5; % Diagonal term
                    end
                end
            end
        catch ME
            error('Error computing influence coefficients: %s', ME.message);
        end

        % Solve for source strengths
        try
            sigma = A \ b;
        catch ME
            error('Error solving for source strengths: %s', ME.message);
        end

        % Compute pressure coefficients
        try
            Cp = compute_pressure_coefficients(distributed_points, sigma, V_inf, alpha);
        catch ME
            error('Error computing pressure coefficients: %s', ME.message);
        end

        % Compute lift coefficient using Kutta-Joukowski theorem
        try
            Cl = compute_lift_coefficient(distributed_points, sigma, V_inf);
        catch ME
            error('Error computing lift coefficient: %s', ME.message);
        end

        % Store results
        Cl_results(k) = Cl;
        Cp_errors{k} = norm(Cp - Cp_exp);

        % Display results for each panel number
        fprintf('Number of Panels: %d\n', n_panels);
        fprintf('Pressure Coefficients:\n');
        disp(Cp);
        fprintf('Lift Coefficient (Cl): %.4f\n', Cl);
        fprintf('Error in Pressure Coefficients: %.4f\n', Cp_errors{k});
        fprintf('Error in Lift Coefficient: %.4f\n', abs(Cl - Cl_exp));
    end

    % Plot results
    try
        figure;
        plot(panel_numbers, Cl_results, '-o', panel_numbers, Cl_exp * ones(size(panel_numbers)), '--r');
        xlabel('Number of Panels');
        ylabel('Lift Coefficient (Cl)');
        legend('Numerical Cl', 'Experimental Cl');
        title('Lift Coefficient vs Number of Panels');

        figure;
        plot(panel_numbers, [Cp_errors{:}], '-o');
        xlabel('Number of Panels');
        ylabel('Error in Pressure Coefficients');
        title('Error in Pressure Coefficients vs Number of Panels');
    catch ME
        error('Error plotting results: %s', ME.message);
    end
end

function panel_points = read_panel_points(filename)
    % Read panel points from a text file
    try
        fid = fopen(filename, 'r');
        if fid == -1
            error('File not found');
        end
        panel_points = textscan(fid, '%f %f', 'Delimiter', ',');
        fclose(fid);
        panel_points = [panel_points{1}, panel_points{2}];
    catch ME
        error('Error reading panel points: %s', ME.message);
    end
end

function distributed_points = distribute_panels(panel_points, n_panels)
    % Distribute panel points
    n_original = size(panel_points, 1);
    t = linspace(0, 1, n_panels + 1);
    distributed_points = zeros(n_panels, 2);

    try
        for i = 1:n_panels
            idx1 = floor((i - 1) * n_original / n_panels) + 1;
            idx2 = floor(i * n_original / n_panels) + 1;
            distributed_points(i, :) = (1 - t(i)) * panel_points(idx1, :) + t(i) * panel_points(idx2, :);
        end
    catch ME
        error('Error distributing panels: %s', ME.message);
    end
end

function A_ij = compute_influence_coefficient(P_i, P_j)
    % Compute influence coefficient A_ij
    x_i = P_i(1); y_i = P_i(2);
    x_j = P_j(1); y_j = P_j(2);
    dx = x_j - x_i;
    dy = y_j - y_i;
    r = sqrt(dx^2 + dy^2);
    A_ij = 0.5 * log((r + dx)^2 + dy^2) / (2 * pi);
end

function Cp = compute_pressure_coefficients(panel_points, sigma, V_inf, alpha)
    % Compute pressure coefficients
    n_panels = size(panel_points, 1);
    Cp = zeros(n_panels, 1);

    try
        for i = 1:n_panels
            V_local = V_inf * cos(alpha - atan2(panel_points(i, 2), panel_points(i, 1)));
            for j = 1:n_panels
                V_local = V_local + sigma(j) * compute_influence_coefficient(panel_points(i, :), panel_points(j, :));
            end
            Cp(i) = 1 - (V_local / V_inf)^2;
        end
    catch ME
        error('Error computing pressure coefficients: %s', ME.message);
    end
end

function Cl = compute_lift_coefficient(panel_points, sigma, V_inf)
    % Compute lift coefficient using Kutta-Joukowski theorem
    n_panels = size(panel_points, 1);
    gamma = 0;

    try
        for i = 1:n_panels
            gamma = gamma + sigma(i) * norm(panel_points(i, :) - panel_points(mod(i-1, n_panels) + 1, :));
        end
        Cl = 2 * pi * gamma / V_inf;
    catch ME
        error('Error computing lift coefficient: %s', ME.message);
    end
end
```

