  const { slug } = router.query;
  const [content, setContent] = useState('');

  useEffect(() => {
    if (slug) {
      fetchDocument(slug);
    }
  }, [slug]);

  const fetchDocument = async (slug) => {
    const docRef = doc(db, 'documents', slug);
    const docSnap = await getDoc(docRef);
    if (docSnap.exists()) {
      setContent(docSnap.data().content);
    } else {
      setContent('');
    }
