import { useState, useEffect } from 'react';
import { Button, Textarea } from '@tailwindcss/forms';

const isClient = typeof window !== 'undefined';

const Editor = ({ content, onChange, onSave }) => {
  const [editorContent, setEditorContent] = useState(content);

  useEffect(() => {
    if (isClient) {
      setEditorContent(content);
    }
  }, [content]);

  const handleContentChange = (e) => {
    const newContent = e.target.value;
    // Apply formatting rules here
    const formattedContent = applyFormatting(newContent);
    setEditorContent(formattedContent);
    onChange(formattedContent);
  };

  const applyFormatting = (content) => {
    // Example formatting rules
    content = content.replace(/\n{3,}/g, '\n\n'); // Limit consecutive newlines to two
    content = content.replace(/ {2,}/g, ' '); // Limit consecutive spaces to one
    return content;
  };

  return (
