      <Textarea
        value={editorContent}
        onChange={handleContentChange}
        className="w-full h-64 p-4 border border-gray-300 rounded-md"
        placeholder="Edit your documentation here..."
      />
      <Button onClick={onSave} className="mt-4 bg-blue-500 text-white px-4 py-2 rounded">
        Save
      </Button>
    </div>
  );
};

export default Editor;
```

