public class PhysicsUtils {
    public static Vector2 smoothVelocityToPosition(Body body, Vector2 targetPosition, float maxSpeed) {
        Vector2 position = body.getPosition();
        Vector2 targetDirection = targetPosition.cpy().sub(position);
        float delta = Gdx.graphics.getDeltaTime();
        Vector2 velocity = targetDirection.scl(delta * maxSpeed * PhysicsSystem.STEP_FREQUENCY);
        return velocity;
    }

    public static Vector2 velocityToPosition(Body body, Vector2 targetPosition, float maxSpeed, float interpolationAlpha) {
        Vector2 position = body.getPosition();
        Vector2 targetDirection = targetPosition.cpy().sub(position);
        float distanceToTarget = targetDirection.len();

        float delta = Gdx.graphics.getDeltaTime();
        float maxDistancePerFrame = maxSpeed * delta * PhysicsSystem.STEP_FREQUENCY;
        Vector2 desiredVelocity = targetDirection.scl(maxSpeed / distanceToTarget);

        if (distanceToTarget < maxDistancePerFrame) {
            velocity = targetDirection;
        } else {
            Vector2 currentVelocity = body.getLinearVelocity();
            velocity = currentVelocity.lerp(desiredVelocity, interpolationAlpha);
        }

        return velocity;
    }

