using UnityEngine;

public class TrajectoryPredictor : MonoBehaviour
{
    public LineRenderer lineRenderer; // LineRenderer component to draw the trajectory
    public Transform canvasTransform; // Reference to the World Space Canvas
    public int segmentCount = 10; // Number of segments to show in the trajectory
    public float predictionForce = 10f; // Force applied to the object when launched
    public float gravity = -9.81f; // Gravity constant

    private Vector3 initialPosition;
    private bool isDragging = false;
    private Rigidbody2D rb;

    void Start()
    {
        // Initialize the LineRenderer
        lineRenderer.positionCount = segmentCount;
        lineRenderer.useWorldSpace = false; // Use local space for UI rendering

        // Get the Rigidbody2D component
        rb = GetComponent<Rigidbody2D>();

        // Set the material for the LineRenderer to make it visible
        lineRenderer.material = new Material(Shader.Find("UI/Default")); // Use UI shader
        lineRenderer.startColor = Color.white;
        lineRenderer.endColor = Color.white;
        lineRenderer.startWidth = 0.1f; // Width of the dots
        lineRenderer.endWidth = 0.1f; // Width of the dots

        // Ensure the LineRenderer is a child of the canvas
        lineRenderer.transform.SetParent(canvasTransform, false);
    }

    void Update()
    {
        if (Input.GetMouseButtonDown(0))
        {
            isDragging = true;
            initialPosition = Camera.main.ScreenToWorldPoint(Input.mousePosition);
            initialPosition.z = 0; // Ensure the position is in the same plane as the UI
        }

        if (isDragging && Input.GetMouseButton(0))
        {
            Vector3 currentPosition = Camera.main.ScreenToWorldPoint(Input.mousePosition);
            currentPosition.z = 0; // Ensure the position is in the same plane as the UI

            Vector3 direction = (currentPosition - initialPosition).normalized;
            ShowTrajectory(direction);
        }

        if (Input.GetMouseButtonUp(0) && isDragging)
        {
            Vector3 currentPosition = Camera.main.ScreenToWorldPoint(Input.mousePosition);
            currentPosition.z = 0; // Ensure the position is in the same plane as the UI

            Vector3 direction = (currentPosition - initialPosition).normalized;
            LaunchObject(direction);
            isDragging = false;
        }
    }

    void ShowTrajectory(Vector3 direction)
    {
        // Calculate the trajectory points
        Vector3[] positions = new Vector3[segmentCount];
        for (int i = 0; i < segmentCount; i++)
        {
            float time = i * 0.1f; // Time step for each segment
            Vector3 velocity = direction * predictionForce;
            Vector3 position = initialPosition + velocity * time + 0.5f * gravity * Vector3.up * time * time;

            // Convert world position to screen position
            Vector3 screenPosition = Camera.main.WorldToScreenPoint(position);

            // Convert screen position to local position in the canvas
            if (RectTransformUtility.ScreenPointToLocalPointInRectangle(
                (RectTransform)canvasTransform, screenPosition, null, out Vector2 localPosition))
            {
                // Set the position of the dot
                positions[i] = new Vector3(localPosition.x, localPosition.y, 0);
            }
            else
            {
                // If the point is outside the canvas, set it to a default value or handle it as needed
                positions[i] = Vector3.zero;
            }
        }

        // Set the positions of the LineRenderer
        lineRenderer.SetPositions(positions);
        lineRenderer.enabled = true;
    }

    void LaunchObject(Vector3 direction)
    {
        if (rb != null)
        {
            rb.velocity = Vector2.zero; // Reset any existing velocity
            rb.AddForce(direction * predictionForce, ForceMode2D.Impulse);
        }

        // Disable the LineRenderer
        lineRenderer.enabled = false;
    }
}
