// Verify the consensus signature
bool verifyConsensusSignature(const std::string& consensus, const std::string& public_key_pem) {
    BIO* bio = BIO_new_mem_buf((void*)public_key_pem.c_str(), -1);
    EVP_PKEY* public_key = PEM_read_bio_PUBKEY(bio, NULL, NULL, NULL);
    BIO_free(bio);

    if (!public_key) {
        std::cerr << "Failed to load public key.\n";
        return false;
    }

    std::string signature;
    std::istringstream iss(consensus);
    std::string line;
    while (std::getline(iss, line)) {
        if (line.find("directory-signature ") == 0) {
            signature = line.substr(20);
            break;
        }
    }

    if (signature.empty()) {
        std::cerr << "No signature found in consensus.\n";
        EVP_PKEY_free(public_key);
        return false;
    }

    std::string message = consensus.substr(0, consensus.find("directory-signature "));

    // Base64 decode the signature
    BIO* b64 = BIO_new(BIO_f_base64());
    BIO_set_flags(b64, BIO_FLAGS_BASE64_NO_NL);  // Do not use newlines to flush buffer
    BIO* bio_mem = BIO_new_mem_buf((void*)signature.c_str(), -1);
    bio_mem = BIO_push(b64, bio_mem);
    unsigned char* decoded_data = NULL;
    long decoded_len = BIO_read(bio_mem, NULL, 0);
    decoded_data = (unsigned char*)OPENSSL_malloc(decoded_len);
    if (decoded_data == NULL) {
        std::cerr << "Failed to allocate memory for decoded data.\n";
        BIO_free_all(bio_mem);
        EVP_PKEY_free(public_key);
        return false;
    }
    BIO_read(bio_mem, decoded_data, decoded_len);
    BIO_free_all(bio_mem);

    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    if (!ctx) {
        std::cerr << "Failed to create EVP_MD_CTX.\n";
        OPENSSL_free(decoded_data);
        EVP_PKEY_free(public_key);
        return false;
    }

    if (EVP_VerifyInit_ex(ctx, EVP_sha256(), NULL) != 1) {
        std::cerr << "Failed to initialize verification context.\n";
        EVP_MD_CTX_free(ctx);
        OPENSSL_free(decoded_data);
        EVP_PKEY_free(public_key);
        return false;
    }

    if (EVP_VerifyUpdate(ctx, message.c_str(), message.size()) != 1) {
        std::cerr << "Failed to update verification context.\n";
        EVP_MD_CTX_free(ctx);
        OPENSSL_free(decoded_data);
        EVP_PKEY_free(public_key);
        return false;
    }

    int result = EVP_VerifyFinal(ctx, decoded_data, decoded_len, public_key);

    EVP_MD_CTX_free(ctx);
    OPENSSL_free(decoded_data);
    EVP_PKEY_free(public_key);

    if (result == 1) {
        std::cout << "Consensus signature verified successfully.\n";
        return true;
    } else {
        std::cerr << "Consensus signature verification failed.\n";
        return false;
    }
}

