// Verify the hidden service descriptor signature
bool verifyDescriptorSignature(const std::string& descriptor, const std::string& public_key_pem) {
    BIO* bio = BIO_new_mem_buf((void*)public_key_pem.c_str(), -1);
    EVP_PKEY* public_key = PEM_read_bio_PUBKEY(bio, NULL, NULL, NULL);
    BIO_free(bio);

    if (!public_key) {
        std::cerr << "Failed to load public key.\n";
        return false;
    }

    std::string signature;
    std::istringstream iss(descriptor);
    std::string line;
    while (std::getline(iss, line)) {
        if (line.find("signature ") == 0) {
            signature = line.substr(10);
            break;
        }
    }

    if (signature.empty()) {
        std::cerr << "No signature found in descriptor.\n";
        EVP_PKEY_free(public_key);
        return false;
    }

    // Base64 decode the signature
    BIO* b64 = BIO_new(BIO_f_base64());
    BIO* bioMem = BIO_new_mem_buf((void*)signature.c_str(), -1);
    bioMem = BIO_push(b64, bioMem);
    unsigned char* decodedSignature = (unsigned char*)malloc(signature.size());
    int decodedSignatureLen = BIO_read(bioMem, decodedSignature, signature.size());
    BIO_free_all(bioMem);

    if (decodedSignatureLen <= 0) {
        std::cerr << "Failed to decode signature.\n";
        EVP_PKEY_free(public_key);
        free(decodedSignature);
        return false;
    }

    std::string message = descriptor.substr(0, descriptor.find("signature "));

    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    if (!ctx) {
        std::cerr << "Failed to create EVP_MD_CTX.\n";
        EVP_PKEY_free(public_key);
        free(decodedSignature);
        return false;
    }

    if (EVP_VerifyInit_ex(ctx, EVP_sha256(), NULL) != 1) {
        std::cerr << "Failed to initialize verification context.\n";
        EVP_MD_CTX_free(ctx);
        EVP_PKEY_free(public_key);
        free(decodedSignature);
        return false;
    }

    if (EVP_VerifyUpdate(ctx, message.c_str(), message.size()) != 1) {
        std::cerr << "Failed to update verification context.\n";
        EVP_MD_CTX_free(ctx);
        EVP_PKEY_free(public_key);
        free(decodedSignature);
        return false;
    }

    int result = EVP_VerifyFinal(ctx, decodedSignature, decodedSignatureLen, public_key);

    EVP_MD_CTX_free(ctx);
    EVP_PKEY_free(public_key);
    free(decodedSignature);

    if (result == 1) {
        std::cout << "Descriptor signature verified successfully.\n";
        return true;
    } else {
        std::cerr << "Descriptor signature verification failed.\n";
        return false;
    }
}

