```javascript
const sharp = require('sharp');
const fs = require('fs');

// Function to add a watermark to an image
async function addWatermark(inputImage, outputImage, watermarkPath) {
  // Load the original image
  const originalImage = await sharp(inputImage).metadata();

  // Load the watermark image
  const watermark = await sharp(watermarkPath).toBuffer();

  // Calculate the appropriate size for the watermark
  const watermarkSize = Math.min(originalImage.width / 4, originalImage.height / 4);
  const resizedWatermark = await sharp(watermark)
    .resize(watermarkSize, watermarkSize)
    .toBuffer();

  // Convert the original image to grayscale for analysis
  const grayImage = await sharp(inputImage).grayscale().toBuffer();

  // Define the four corners
  const corners = [
    { x: 0, y: 0 }, // top-left
    { x: originalImage.width - watermarkSize, y: 0 }, // top-right
    { x: 0, y: originalImage.height - watermarkSize }, // bottom-left
    { x: originalImage.width - watermarkSize, y: originalImage.height - watermarkSize } // bottom-right
  ];

  // Calculate the average pixel intensity in each corner
  const intensities = await Promise.all(corners.map(async (corner) => {
    const box = [corner.x, corner.y, corner.x + watermarkSize, corner.y + watermarkSize];
    const region = await sharp(grayImage).extract({ left: box[0], top: box[1], width: watermarkSize, height: watermarkSize }).toBuffer();
    const intensity = await sharp(region).stats().then(stats => stats.mean);
    return intensity;
  }));

  // Determine the least busy corner
  const leastBusyCornerIndex = intensities.indexOf(Math.min(...intensities));
  const leastBusyCorner = corners[leastBusyCornerIndex];

  // Composite the watermark onto the original image with transparency
  await sharp(inputImage)
    .composite([
      {
        input: resizedWatermark,
        left: leastBusyCorner.x,
        top: leastBusyCorner.y,
        blend: 'atop', // Use atop blending mode for transparency
        premultiplied: true,
        tile: false,
        density: 72
      }
    ])
    .toFile(outputImage);

  console.log(`Watermarked image saved to ${outputImage}`);
}

